UPDATE pois
SET rating = (
  SELECT ROUND(AVG(r.rating), 1)
  FROM ratings r
  WHERE r.target_type = 'poi'
    AND r.target_id = #{id}
)
WHERE id = #{id}

UPDATE foods
SET rating = (
  SELECT ROUND(AVG(r.rating), 1)
  FROM ratings r
  WHERE r.target_type = 'food'
    AND r.target_id = #{id}
)
WHERE id = #{id}
